  const tips = fx.filter((m) => Object.keys(MK).some((k) => { const q = pick(m, k); return q && !q.model && q.c >= MIN[k]; })).length;
  const first = up.slice(0, 2).map((m) => `${esc(m.h)} v ${esc(m.a)}`).join(' and ');
