  const rel = avg > ALLAVG + 0.25 ? `That is more than the ${ALLAVG.toFixed(2)} goals a game across every league we track, so ${name} leans towards the goals markets.` : avg < ALLAVG - 0.25 ? `That is less than the ${ALLAVG.toFixed(2)} goals a game across every league we track, so ${name} is a tighter league than most.` : `That is close to the ${ALLAVG.toFixed(2)} goals a game across every league we track, so ${name} sits in the middle of the pack.`;
  const mk = [];
  if (P(o25) >= 55) mk.push(`Over 2.5 goals has been the more common outcome here, landing ${P(o25)}% of the time, so the “over” side starts with a head start before you look at any single game.`);
  else if (P(o25) <= 45) mk.push(`Over 2.5 landed only ${P(o25)}% of the time, which makes under 2.5 and over 1.5 the markets that fit the league’s pattern better.`);
  else mk.push(`Over 2.5 landed ${P(o25)}% of the time, almost an even split, so game-by-game information matters more than the league label here.`);
  if (P(bt) >= 55) mk.push(`Both teams scored in ${P(bt)}% of games, so BTTS “Yes” has suited this league.`); else if (P(bt) <= 45) mk.push(`Both teams scored in just ${P(bt)}% of games, so one-sided scorelines are common and BTTS “No” deserves a look.`); else mk.push(`BTTS landed in ${P(bt)}% of games, close to an even call.`);
  const homeNote = P(hw) >= 47 ? `Home advantage is strong: home teams won ${P(hw)}% of games.` : P(hw) <= 38 ? `Home advantage is weak here: home teams won only ${P(hw)}% of games, with away sides taking ${P(aw)}%.` : `Home teams won ${P(hw)}% of games, which is about what you’d expect.`;
  const lowN = n < 60 ? ` The sample is still small, so treat every percentage as an early guide.` : '';
  const html = `<div class="prose"><h2>${name} goals and results profile</h2><p>We hold ${n} ${name} results between clubs in the current table. They produced ${tg} goals, an average of ${avg.toFixed(2)} per game. ${rel}</p><div class="sc"><table><thead><tr><th>Stat</th><th>${name}</th></tr></thead><tbody><tr><td>Over 1.5 goals</td><td>${P(o15)}%</td></tr><tr><td>Over 2.5 goals</td><td>${P(o25)}%</td></tr><tr><td>Over 3.5 goals</td><td>${P(o35)}%</td></tr><tr><td>Both teams to score</td><td>${P(bt)}%</td></tr><tr><td>Home win / draw / away win</td><td>${P(hw)}% / ${P(dr)}% / ${P(aw)}%</td></tr><tr><td>Goalless draws</td><td>${z}</td></tr></tbody></table></div><h2>Which markets fit ${name}?</h2><p>${mk.join(' ')}${lowN}</p><h2>Home advantage and the draw</h2><p>${homeNote} Draws ended ${P(dr)}% of games. Home sides scored ${hg.toFixed(2)} a game and away sides ${ag.toFixed(2)}. ${P(dr) >= 28 ? `With that many draws, double chance and draw no bet are worth comparing with the plain 1X2 price.` : `Draws are not especially common, so the 1X2 market is rarely a lottery on the middle result.`}</p><h2>Extremes from the games we hold</h2><p>The highest-scoring game was ${esc(top[1])} ${top[3]}–${top[4]} ${esc(top[2])} (${top[0]}), and the biggest margin came in ${esc(big[1])} ${big[3]}–${big[4]} ${esc(big[2])} (${big[0]}). ${z ? `${z} game${z == 1 ? '' : 's'} finished 0–0.` : 'None finished 0–0.'}</p><p class="mut">Want the same idea for another league or a market? See the <a href="over-under-goals-betting-explained.html">over/under goals guide</a> and the <a href="how-it-works.html">methodology</a>.</p></div>`;
